    ('0902','WILIAM BERNARD CALDERON DE LEÓN','GT-TSE-CME-2023-0902','{"year":2023,"total":11,"titular_total":8,"substitute_total":3,"groups":[{"party":"VAMOS","seats":5},{"party":"UNE","seats":2},{"party":"Coalición Valor-Unionista","seats":1}],"members":[{"office":"ALCALDE","name":"WILIAM BERNARD CALDERON DE LEÓN","party":"VAMOS","source_page":2,"source_office_text":null},{"office":"CONCEJAL 1","name":"RONY EDUARDO MAZARIEGOS FIGUEROA","party":"VAMOS","source_page":3,"source_office_text":"CONCEJAL PRIMERO"},{"office":"CONCEJAL 2","name":"JOSE MANUEL TIGUILA SOC","party":"VAMOS","source_page":3,"source_office_text":"CONCEJAL SEGUNDO"},{"office":"CONCEJAL 3","name":"SERGIO DANILO GRAMAJO ESTRADA","party":"UNE","source_page":3,"source_office_text":"CONCEJAL TERCERO"},{"office":"CONCEJAL 4","name":"RITO ESTUARDO OVALLE BARRIOS","party":"UNE","source_page":3,"source_office_text":"CONCEJAL CUARTO"},{"office":"CONCEJAL 5","name":"LUIS CIPRIANO ESTRADA BARRIENTOS","party":"Coalición Valor-Unionista","source_page":3,"source_office_text":"CONCEJAL QUINTO"},{"office":"CONCEJAL SUPLENTE 1","name":"FRANKLIN NOEL ESTRADA MORALES","party":"VAMOS","source_page":3,"source_office_text":"PRIMER CONCEJAL SUPLENTE"},{"office":"CONCEJAL SUPLENTE 2","name":"IVAN DE JESUS MAZARIEGOS RAMIREZ","party":"UNE","source_page":3,"source_office_text":"SEGUNDO CONCEJAL SUPLENTE"},{"office":"SÍNDICO 1","name":"JOSE JORGE SLIM DE LEÓN RODAS","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO 2","name":"WELMER DANILO DE LEÓN GRAMAJO","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO SUPLENTE","name":"ANTONIETA LISETT DE LEON SOTOVANDO","party":"VAMOS","source_page":2,"source_office_text":"SÍNDICO SUPLENTE"}],"mayor":"WILIAM BERNARD CALDERON DE LEÓN","winner_party":"VAMOS","detail_status":"FULL_MEMBERS_OFFICIAL_AGREEMENT","warnings":[],"source_id":"GT-TSE-CME-2023-0902","source_url":"https://tse.org.gt/images/ss/cme/que_04-2023.pdf","source_page_url":"https://tse.org.gt/comunicacion/publicaciones/corporaciones-municipales-electas-2023/corporacion-quetzaltenango","agreement_number":4,"applied_amendments":[]}'::jsonb,'[]'::jsonb),
    ('0903','OMAR MOISES DE LEON CIFUENTES','GT-TSE-CME-2023-0903','{"year":2023,"total":11,"titular_total":8,"substitute_total":3,"groups":[{"party":"VAMOS","seats":5},{"party":"BIEN","seats":1},{"party":"CABAL","seats":1},{"party":"TODOS","seats":1}],"members":[{"office":"ALCALDE","name":"OMAR MOISES DE LEON CIFUENTES","party":"VAMOS","source_page":2,"source_office_text":null},{"office":"CONCEJAL 1","name":"JULIO CESAR TEBALAN CHAVEZ","party":"VAMOS","source_page":3,"source_office_text":"CONCEJAL PRIMERO"},{"office":"CONCEJAL 2","name":"MIGUEL ANGEL VENTURA IXCHOP","party":"VAMOS","source_page":3,"source_office_text":"CONCEJAL SEGUNDO"},{"office":"CONCEJAL 3","name":"Eduardo Baldomero Alvarez Paxtor","party":"BIEN","source_page":3,"source_office_text":"CONCEJAL TERCERO"},{"office":"CONCEJAL 4","name":"EFRAIN JOSE MAZARIEGOS YAC","party":"CABAL","source_page":3,"source_office_text":"CONCEJAL CUARTO"},{"office":"CONCEJAL 5","name":"CATARINO GONZALEZ LOPEZ","party":"TODOS","source_page":3,"source_office_text":"CONCEJAL QUINTO"},{"office":"CONCEJAL SUPLENTE 1","name":"NELSON GUSTAVO COTUC GARCIA","party":"VAMOS","source_page":3,"source_office_text":"PRIMER CONCEJAL SUPLENTE"},{"office":"CONCEJAL SUPLENTE 2","name":"DIEGO OXLAJ HUINAC","party":"BIEN","source_page":3,"source_office_text":"SEGUNDO CONCEJAL SUPLENTE"},{"office":"SÍNDICO 1","name":"ARIEL OFTALI DE LEON DIAZ","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO 2","name":"ERICK RENE GONZALEZ GOMEZ","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO SUPLENTE","name":"ISAIAS CHAVEZ ALVAREZ","party":"VAMOS","source_page":2,"source_office_text":"SÍNDICO SUPLENTE"}],"mayor":"OMAR MOISES DE LEON CIFUENTES","winner_party":"VAMOS","detail_status":"FULL_MEMBERS_OFFICIAL_AGREEMENT","warnings":[],"source_id":"GT-TSE-CME-2023-0903","source_url":"https://tse.org.gt/images/ss/cme/que_05-2023.pdf","source_page_url":"https://tse.org.gt/comunicacion/publicaciones/corporaciones-municipales-electas-2023/corporacion-quetzaltenango","agreement_number":5,"applied_amendments":[]}'::jsonb,'[]'::jsonb)
), targets as (
  select p.id, p.profile, p.source_manifest, i.*
  from incoming i
  join public.municipalities m
    on m.country_code = 'GT'
   and m.municipality_code = i.municipality_code
  join data_vault.municipality_intelligence_profiles_v1 p
    on p.municipality_id = m.id
), patched as (
  select
    id,
    source_id,
    amendments,
    jsonb_set(
      jsonb_set(
        profile,
        '{electoral_history,councils}',
        coalesce((
          select jsonb_agg(council_item order by (council_item->>'year')::integer)
          from jsonb_array_elements(coalesce(profile->'electoral_history'->'councils', '[]'::jsonb)) council_item
          where (council_item->>'year')::integer <> 2023
        ), '[]'::jsonb) || jsonb_build_array(council),
        true
      ),
      '{electoral_history,elections}',
      coalesce((
        select jsonb_agg(
          case when (election->>'year')::integer = 2023 then
            jsonb_set(
              jsonb_set(election, '{winner_candidate}', to_jsonb(mayor), true),
              '{results}',
              coalesce((
                select jsonb_agg(
                  case when (result->>'rank')::integer = 1
                    then jsonb_set(result, '{candidate}', to_jsonb(mayor), true)
                    else result
                  end
                  order by (result->>'rank')::integer
                )
                from jsonb_array_elements(coalesce(election->'results', '[]'::jsonb)) result
              ), '[]'::jsonb),
              true
            )
          else election end
          order by (election->>'year')::integer
        )
        from jsonb_array_elements(coalesce(profile->'electoral_history'->'elections', '[]'::jsonb)) election
      ), '[]'::jsonb),
      true
    ) as profile
  from targets
)
update data_vault.municipality_intelligence_profiles_v1 p
set
  profile = jsonb_set(
    patched.profile,
    '{source_manifest}',
    coalesce(patched.profile->'source_manifest', '{}'::jsonb)
      || jsonb_build_object('municipal_council_2023', patched.source_id)
      || case when jsonb_array_length(patched.amendments) > 0
           then jsonb_build_object('municipal_council_2023_amendments', patched.amendments)
           else '{}'::jsonb
         end,
    true
  ),
  source_manifest = coalesce(p.source_manifest, '{}'::jsonb)
    || jsonb_build_object('municipal_council_2023', patched.source_id)
    || case when jsonb_array_length(patched.amendments) > 0
         then jsonb_build_object('municipal_council_2023_amendments', patched.amendments)
         else '{}'::jsonb
       end,
  generated_at = now(),
  updated_at = now()
from patched
where p.id = patched.id;

do $$
declare
  loaded integer;
begin
  select count(*) into loaded
  from data_vault.municipality_intelligence_profiles_v1 p
  join public.municipalities m on m.id = p.municipality_id
  where m.municipality_code in ('0101', '0102', '0103', '0104', '0105', '0106', '0107', '0108', '0109', '0110', '0111', '0112', '0113', '0114', '0115', '0116', '0117', '0201', '0202', '0203', '0204', '0205', '0206', '0207', '0208', '0301', '0302', '0303', '0304', '0305', '0306', '0307', '0308', '0309', '0310', '0311', '0312', '0313', '0314', '0315', '0316', '0401', '0402', '0403', '0404', '0405', '0406', '0407', '0408', '0409', '0410', '0411', '0412', '0413', '0414', '0415', '0416', '0501', '0502', '0503', '0504', '0505', '0506', '0507', '0508', '0509', '0510', '0511', '0512', '0513', '0514', '0601', '0602', '0603', '0604', '0605', '0606', '0607', '0608', '0609', '0610', '0611', '0612', '0613', '0614', '0701', '0702', '0703', '0704', '0705', '0706', '0707', '0708', '0709', '0710', '0711', '0712', '0713', '0714', '0715', '0716', '0717', '0718', '0719', '0801', '0802', '0803', '0804', '0805', '0806', '0807', '0808', '0901', '0902', '0903')
    and p.profile->'source_manifest' ? 'municipal_council_2023'
    and jsonb_array_length(
      coalesce(p.profile->'electoral_history'->'councils', '[]'::jsonb)
    ) = 4;
  if loaded <> 115 then
    raise exception 'TSE 2023 corporation part 01: expected 115, loaded %', loaded;
  end if;
end $$;

commit;

